setInterval(()=>{if(!document.hidden&&!ui.busy)refresh(false);},1800);
setInterval(updateTimers,1000);
(async()=>{try{await bootstrap();if(!ui.page&&B.player)ui.page='hunt';if((isAdminView()&&B.admin)||B.player){await refresh(true);await restorePhoto();}render();}catch(e){$('#app').innerHTML=`<section class="error-page"><h1>Let's reconnect.</h1><p>${esc(errorMessage(e))}</p><button class="btn" id="initial-retry">Retry connection</button><p class="tiny muted mt">For the multiplayer build, start the server with python run.py. Do not open static/index.html directly.</p></section>`;$('#initial-retry')?.addEventListener('click',()=>location.reload());}})();
